[
  {
    "alert_id": "EX3_001",
    "title": "Untreated hypothyroidism likely driving weight gain",
    "message": "Patient has TSH 12.4 mIU/L with low Free T4, dry skin, periorbital puffiness, delayed ankle reflexes, constipation, and cold intolerance — all classic features of inadequately treated hypothyroidism. She admits often forgetting her levothyroxine. The 9 kg weight gain over one year is being attributed to DTG, but uncontrolled hypothyroidism is a strong alternative explanation. The clinician plans to switch DTG without first addressing levothyroxine adherence and dose optimisation. Switching DTG in a virologically suppressed patient (VL <50) without correcting the thyroid dysfunction may not resolve the weight gain and risks losing a well-tolerated, high-barrier regimen.",
    "issue_type": "plan_review",
    "severity": "high",
    "recommended_action": "Optimise levothyroxine adherence and up-titrate dose to normalise TSH before attributing weight gain to DTG. Reassess symptoms and weight after thyroid correction before switching ART.",
    "citations": []
  },
  {
    "alert_id": "EX3_002",
    "title": "DTG hyperglycemia risk: multiple risk factors present",
    "message": "Guidelines require screening for hyperglycemia risk before DTG use; risk factors include age ≥40, BMI ≥25, and history of hypertension. This patient is 45, BMI 33, and on TLD since January 2023. Guidelines state that clients with 2 or more risk factors and high baseline glucose should not be on DTG. Her fasting glucose is 5.6 mmol/L (below the >6.95 threshold). However, guidelines recommend glucose monitoring every 3 months for the first year for those with risk factors. No repeat glucose has been checked since starting DTG over 3 years ago, representing a monitoring gap.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Assess hyperglycemia risk factors formally. If continuing DTG, monitor fasting glucose every 3 months. If switching, use EFV400 or ATV/r per guidelines for hyperglycemia risk.",
    "citations": [
      {"page_number": 4, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p4_c2"},
      {"page_number": 38, "chunk_id": "hiv_guidelines_co_infectionscreening.extraction__hiv_guidelines_co_infectionscreening.extraction__p38_c2"}
    ]
  },
  {
    "alert_id": "EX3_003",
    "title": "Dyslipidemia — Grade 2 cholesterol and LDL",
    "message": "Guideline toxicity grading classifies fasting total cholesterol 6.4 mmol/L as Grade 2 (moderate, 6.19–7.77) and LDL 4.2 mmol/L as Grade 2 (4.12–4.90). Triglycerides 2.3 mmol/L fall in Grade 1. TDF can contribute to dyslipidemia, though DTG is generally lipid-neutral. Uncontrolled hypothyroidism is also a well-recognised cause of elevated cholesterol and may be a major contributor here. The clinician's plan does not address the dyslipidemia or its relationship to thyroid status.",
    "issue_type": "toxicity",
    "severity": "moderate",
    "recommended_action": "Reassess lipid panel after thyroid function is corrected. If dyslipidemia persists, consider ART substitution or lipid-lowering therapy per guideline side-effect management tables.",
    "citations": [
      {"page_number": 32, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p32_c1"}
    ]
  },
  {
    "alert_id": "EX3_004",
    "title": "Overdue TDF renal monitoring — creatinine not checked in 6 months",
    "message": "Guidelines require serum creatinine and eGFR every 12 months for patients on TDF. The last creatinine was 72 umol/L on 2025-08-12, 196 days before this visit. While this is within the 12-month interval, no renal monitoring is included in today's plan. Given the patient's weight gain, new metabolic abnormalities, and potential switch decision, a current renal function assessment would inform safe continuation of TDF or selection of an alternative backbone.",
    "issue_type": "monitoring_gap",
    "severity": "low",
    "recommended_action": "Check serum creatinine and eGFR at this visit to confirm TDF renal safety and guide regimen decisions if switching from DTG.",
    "citations": [
      {"page_number": 27, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p27_c2"}
    ]
  }
]
